{"command":"python3 - <<'PY'
import json
calls=[]
add=lambda n,a:calls.append({'name':n,'arguments':a})
add('module_new',{'channels':8,'name':'Cipher Bloom'})
add('song_set',{'bpm':140,'speed':3,'length':8,'loop_start':0,'name':'Cipher Bloom'})
for i,p in enumerate([0,1,2,3,4,5,6,7]): add('order_set',{'position':i,'pattern':p})
for p in range(8): add('pattern_set_length',{'pattern':p,'rows':64})
# load samples/instruments
names=['kick','snare','hat','bass','lead','pad']
for i,n in enumerate(names,1):
    add('sample_load',{'path':f'/workspace/snd/{n}.wav','instrument':i})
    add('instrument_set',{'instrument':i,'name':n.upper()})
# loops for tonal
add('sample_set',{'instrument':4,'loop_start':0,'loop_length':256,'flags':1,'volume':56})
add('sample_set',{'instrument':5,'loop_start':0,'loop_length':256,'flags':1,'volume':46})
add('sample_set',{'instrument':6,'loop_start':0,'loop_length':512,'flags':1,'volume':36})
add('sample_set',{'instrument':1,'volume':64})
add('sample_set',{'instrument':2,'volume':52})
add('sample_set',{'instrument':3,'volume':34})

minor=[0,2,3,5,7,8,10]
def n(o,s): return 12*o+s
root_seq=[5,3,0,7]
# patterns
for pat in range(8):
    for r in range(0,64,4):
        add('pattern_set_cell',{'pattern':pat,'row':r,'channel':0,'note':n(3,0),'instrument':1})
        if r in [16,48]: add('pattern_set_cell',{'pattern':pat,'row':r,'channel':0,'note':n(3,0),'instrument':1,'volume':40})
    for r in [8,24,40,56]:
        add('pattern_set_cell',{'pattern':pat,'row':r,'channel':1,'note':n(3,5),'instrument':1,'volume':42})
    for r in [16,48]:
        add('pattern_set_cell',{'pattern':pat,'row':1+r,'channel':1,'note':n(3,7),'instrument':2})
    for r in range(0,64,4):
        add('pattern_set_cell',{'pattern':pat,'row':r+2,'channel':2,'note':n(5,0),'instrument':3,'volume':22})
        if pat>=2: add('pattern_set_cell',{'pattern':pat,'row':r+3,'channel':2,'note':n(5,0),'instrument':3,'volume':18})
    root=root_seq[pat%4]
    for r in [0,8,16,24,32,40,48,56]:
        step=[0,0,3,0,7,0,10,7][(r//8)%8]
        add('pattern_set_cell',{'pattern':pat,'row':r,'channel':3,'note':n(2,(root+step)%12),'instrument':4,'volume':50})
    chord=[root,(root+3)%12,(root+7)%12]
    for rr in [0,16,32,48]:
        for i,ch in enumerate(chord):
            add('pattern_set_cell',{'pattern':pat,'row':rr+i*2,'channel':4,'note':n(4,ch),'instrument':6,'volume':28})

# melodies for sections
melA=[0,2,3,7,8,7,3,2]
melB=[10,8,7,3,2,3,7,8]
for idx,pat in enumerate([2,3,6,7]):
    mel=melA if idx%2==0 else melB
    root=root_seq[pat%4]
    for i,st in enumerate(mel):
        row=i*8
        add('pattern_set_cell',{'pattern':pat,'row':row,'channel':5,'note':n(5,(root+st)%12),'instrument':5,'volume':44})
        add('pattern_set_cell',{'pattern':pat,'row':row+4,'channel':5,'note':n(5,(root+st+12)%12),'instrument':5,'volume':30})

# intro/break thinning
for pat in [0,1]:
    for r in range(64):
        add('cell_clear',{'pattern':pat,'row':r,'channel':5})
for pat in [4,5]:
    for r in range(64):
        add('cell_clear',{'pattern':pat,'row':r,'channel':0})
        if r%8 not in [0,4]: add('cell_clear',{'pattern':pat,'row':r,'channel':2})

with open('/workspace/seq.json','w') as f: json.dump(calls,f)
print(len(calls))
